39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String telephone = toE164(owner.getTelephone());
106	        if (telephone == null) {
107	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
108	        }
109	        owner.setTelephone(telephone);
110	        if (owner.getEmail() != null) {
111	            owner.setEmail(owner.getEmail().toLowerCase());
112	        }
113	        if (owner.getRegistrationDate() == null) {
114	            owner.setRegistrationDate(LocalDate.now());
115	        }
116	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.CONFLICT);
118	        }
119	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
130	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
131	        if (currentOwner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        currentOwner.setAddress(ownerFieldsDto.getAddress());
135	        currentOwner.setCity(ownerFieldsDto.getCity());
136	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
137	        currentOwner.setLastName(ownerFieldsDto.getLastName());
138	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
139	        String email = ownerFieldsDto.getEmail();
140	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
141	        this.clinicService.saveOwner(currentOwner);
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Transactional
147	    @Override
148	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        this.clinicService.deleteOwner(owner);
154	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Pet pet = petMapper.toPet(petFieldsDto);
166	        owner.setId(ownerId);
167	        pet.setOwner(owner);
168	        pet.getType().setName(null);
169	        this.clinicService.savePet(pet);
170	        PetDto petDto = petMapper.toPetDto(pet);
171	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
172	            .buildAndExpand(pet.getId()).toUri());
173	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner != null) {
181	            Pet currentPet = this.clinicService.findPetById(petId);
182	            if (currentPet != null) {
183	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
184	                currentPet.setName(petFieldsDto.getName());
185	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
186	                this.clinicService.savePet(currentPet);
187	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	            }
189	        }
190	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
196	        HttpHeaders headers = new HttpHeaders();
197	        Visit visit = visitMapper.toVisit(visitFieldsDto);
198	        Pet pet = new Pet();
199	        pet.setId(petId);
200	        visit.setPet(pet);
201	        this.clinicService.saveVisit(visit);
202	        VisitDto visitDto = visitMapper.toVisitDto(visit);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
204	            .buildAndExpand(visit.getId()).toUri());
205	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
206	    }
207	
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner != null) {
214	            Pet pet = owner.getPet(petId);
215	            if (pet != null) {
216	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
221	
222	    /**
223	     * Build the next customer code, formatted {@code <LAST3>-<NNNN>}: LAST3 is the
224	     * upper-cased first three letters of the given last name and NNNN is a global
225	     * 4-digit zero-padded sequence equal to one more than the current number of
226	     * owners (e.g. {@code SMI-0007}).
227	     *
228	     * @param lastName the owner's last name
229	     * @return the assigned customer code
230	     */
231	    private String nextCustomerCode(String lastName) {
232	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
233	        long sequence = this.clinicService.findAllOwners().size() + 1L;
